-- Laudo pericial: modelo do Word editável no sistema, campos fixos (Diretor etc.) e laudos emitidos

create table modelos (
  chave          text primary key,
  arquivo        bytea not null,
  nome_arquivo   text not null,
  atualizado_em  timestamptz not null default now(),
  atualizado_por integer references usuarios(id)
);

create table laudos (
  id         serial primary key,
  nota_id    integer not null references notas(id) on delete cascade,
  protocolo  text,
  dados      jsonb not null,
  criado_por integer references usuarios(id),
  criado_em  timestamptz not null default now()
);
create index laudos_nota on laudos (nota_id, criado_em desc);

-- modelo padrão: o mesmo laudo do sistema antigo, com marcadores {{...}}
