-- cópia do modelo padrão, para poder restaurá-lo depois de trocar o modelo
insert into modelos (chave, arquivo, nome_arquivo)
  select 'laudo_pericial_padrao', arquivo, nome_arquivo from modelos where chave = 'laudo_pericial';
